-- Seed menu Qahwa. Ganti 'qahwa' di bawah dengan slug tokomu lalu jalankan di SQL Editor.
do $$
declare sid uuid; cid uuid;
begin
  select id into sid from shops where slug = 'qahwa';
  if sid is null then raise exception 'toko dengan slug itu belum ada'; end if;
  select id into cid from categories where shop_id = sid and name = 'Best Seller';
  select id into cid from categories where shop_id = sid and name = 'Espresso';
  select id into cid from categories where shop_id = sid and name = 'Juice';
  select id into cid from categories where shop_id = sid and name = 'Soft Based Drinks';
  select id into cid from categories where shop_id = sid and name = 'Latte or Float';
  select id into cid from categories where shop_id = sid and name = 'Other Menu';
  select id into cid from categories where shop_id = sid and name = 'Based Soda';
  select id into cid from categories where shop_id = sid and name = 'Nasi Goreng';
  select id into cid from categories where shop_id = sid and name = 'Nasi Goreng Kampung';
  select id into cid from categories where shop_id = sid and name = 'Nasi Goreng Ijo';
  select id into cid from categories where shop_id = sid and name = 'Nasi Goreng Pataya';
  select id into cid from categories where shop_id = sid and name = 'Snack';
  select id into cid from categories where shop_id = sid and name = 'Chicken Katsu';
  select id into cid from categories where shop_id = sid and name = 'Martabak';
  select id into cid from categories where shop_id = sid and name = 'Kue/Mie Tiaw';
  select id into cid from categories where shop_id = sid and name = 'Toom Yum';
  select id into cid from categories where shop_id = sid and name = 'Roti Canai';
  select id into cid from categories where shop_id = sid and name = 'Roti Bakar';
  select id into cid from categories where shop_id = sid and name = 'Burgers';
end $$;
